// Ciclo for classico: soma dos primeiros 5 numeros inteiros
let soma = 0;
for (let i = 1; i <= 5; i++) {
  soma += i;
}
console.log(soma); // 15

// Contagem decrescente
for (let i = 5; i > 0; i--) {
  console.log(`Faltam ${i} segundos`);
}

// Multiplas variaveis na mesma instrucao for
for (let i = 0, j = 10; i < j; i++, j--) {
  console.log(i, j);
}

let saldo = 100;
const custoPorJogada = 15;
let jogadas = 0;

while (saldo >= custoPorJogada) {
  saldo -= custoPorJogada;
  jogadas++;
}

console.log(`Foram possiveis ${jogadas} jogadas`);
console.log(`Sobrou um saldo de ${saldo}`);

// Diferenca fundamental: o do...while executa o bloco pelo menos uma vez,
// mesmo que a condicao seja falsa logo a partida
let x = 10;

while (x < 5) {
  console.log("Isto nunca e impresso, porque a condicao ja comeca falsa");
}

do {
  console.log("Isto e impresso uma vez, porque o do...while testa a condicao so no fim");
} while (x < 5);

// Caso pratico: pedir um PIN ate acertar ou esgotar as tentativas
const pinCorreto = "1234";
const tentativasDoUtilizador = ["0000", "1111", "1234"];
let tentativas = 0;
let pin;

do {
  pin = tentativasDoUtilizador[tentativas];
  tentativas++;
} while (pin !== pinCorreto && tentativas < tentativasDoUtilizador.length);

if (pin === pinCorreto) {
  console.log(`Acesso concedido na tentativa ${tentativas}`);
} else {
  console.log("Acesso bloqueado");
}

// As duas formas seguintes produzem o mesmo numero de iteracoes (0, 1 e 2)
for (let i = 0; i < 3; i++) {
  console.log("for:", i);
}

let i = 0;
while (i < 3) {
  console.log("while:", i);
  i++;
}

// ERRO COMUM: esquecer de atualizar a variavel de controlo
// (este bloco, se descomentado, nunca para)
// let i = 0;
// while (i < 5) {
//   console.log(i);
// }

// Correto: o incremento garante que a condicao acaba por ser falsa
let i = 0;
while (i < 5) {
  console.log(i);
  i++;
}

// Loop infinito intencional, com saida controlada por break
// (break sera explicado em detalhe na proxima aula; aqui serve
// apenas para sair de um while (true) quando a condicao de sucesso se verificar)
let tentativa = 0;

while (true) {
  tentativa++;
  const sucesso = tentativa >= 3;

  if (sucesso) {
    console.log(`Sucesso na tentativa ${tentativa}`);
    break;
  }
}

const precos = [45, 120, 78, 300, 15, 999, 60, 210, 5, 88];

// Menos eficiente: le precos.length e recalcula um valor fixo em cada iteracao
let contagemMau = 0;
for (let i = 0; i < precos.length; i++) {
  const limite = 50 * 2; // resultado sempre igual a 100, nao depende de i
  if (precos[i] > limite) {
    contagemMau++;
  }
}

// Mais eficiente: guarda o comprimento e o valor fixo uma unica vez, antes do ciclo
const total = precos.length;
const limite = 50 * 2;
let contagemBom = 0;
for (let i = 0; i < total; i++) {
  if (precos[i] > limite) {
    contagemBom++;
  }
}

console.log(contagemBom); // 4

