const numero = 7;

for (let i = 1; i <= 10; i++) {
  console.log(`${numero} x ${i} = ${numero * i}`);
}

let saldo = 250;
const levantamento = 40;
let semanas = 0;

while (saldo >= levantamento) {
  saldo -= levantamento;
  semanas++;
}

console.log(`Semanas de levantamento possiveis: ${semanas}`);
console.log(`Saldo final: ${saldo}`);

let resultado;
let lancamentos = 0;
const maximoLancamentos = 10;

do {
  resultado = Math.floor(Math.random() * 6) + 1;
  lancamentos++;
} while (resultado !== 6 && lancamentos < maximoLancamentos);

if (resultado === 6) {
  console.log(`Saiu um 6 ao fim de ${lancamentos} lancamento(s)`);
} else {
  console.log(`Nao saiu um 6 nos ${maximoLancamentos} lancamentos permitidos`);
}

exercises.statement:
O codigo seguinte deveria percorrer o array precos e contar quantos precos sao superiores a 100, mas contem um erro que o transforma num ciclo infinito:

const precos = [50, 120, 80, 200, 99, 150];
let contagem = 0;

for (let i = 0; i < precos.length; i--) {
  if (precos[i] > 100) {
    contagem++;
  }
}

console.log(contagem);

Corrija o erro, mantendo um ciclo for classico e a mesma logica de contagem, e depois melhore a performance garantindo que o comprimento do array so e lido uma vez, antes de o ciclo comecar.

